#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef unsigned long long State;

int main() {
    State state = 0;
    char line[256];

    while (fgets(line, sizeof(line), stdin)) {
        // Remove newline
        line[strcspn(line, "\n")] = 0;

        if (strlen(line) == 0) continue;

        char op;
        int index;

        if (sscanf(line, "%c %d", &op, &index) >= 1) {
            switch (op) {
                case 't': // test flag
                    if (index < 0 || index > 63) {
                        printf("0\n");
                    } else {
                        printf("%d\n", (state >> index) & 1);
                    }
                    break;

                case 's': // set flag
                    if (index >= 0 && index <= 63) {
                        state |= (1ULL << index);
                    }
                    break;

                case 'c': // clear flag
                    if (index >= 0 && index <= 63) {
                        state &= ~(1ULL << index);
                    }
                    break;

                case 'f': // flip flag
                    if (index >= 0 && index <= 63) {
                        state ^= (1ULL << index);
                    }
                    break;

                case 'a': // aggregate info
                    if (index == 0) {
                        // count of ON flags
                        int count = __builtin_popcountll(state);
                        printf("%d\n", count);
                    } else if (index == 1) {
                        // parity (1 if odd number of ON flags)
                        printf("%d\n", __builtin_parityll(state));
                    } else if (index == 2) {
                        // all flags ON?
                        printf("%d\n", state == 0xFFFFFFFFFFFFFFFFULL ? 1 : 0);
                    } else if (index == 3) {
                        // any flag ON?
                        printf("%d\n", state != 0 ? 1 : 0);
                    } else if (index == 4) {
                        // none flag ON?
                        printf("%d\n", state == 0 ? 1 : 0);
                    } else if (index == 5) {
                        // value of state
                        printf("%llu\n", state);
                    }
                    break;
            }
        }
    }

    return 0;
}

