        } else if (strcmp(op, "TEST") == 0) {
            int i;
            scanf("%d", &i);
            printf("%d\n", (flags >> i) & 1 ? 1 : 0);
        } else if (strcmp(op, "COUNT") == 0) {
            int count = __builtin_popcountll(flags);
