        } else if (op[0] == 's') {          // set x
            int x;
            scanf("%d", &x);
            state |= (1ULL << x);
        } else if (op[0] == 'c') {          // clear x
            int x;
            scanf("%d", &x);
            state &= ~(1ULL << x);
        } else if (op[0] == 'f') {          // flip x
            int x;
            scanf("%d", &x);
            state ^= (1ULL << x);
        } else if (op[0] == 'a') {          // all
            printf("%llu\n", (unsigned long long)state);
        } else if (op[0] == 'c' && op[1] == 'o') {
            // unreachable with current ordering, kept for completeness
        } else if (op[0] == 'n') {          // none
            printf("%d\n", state == 0 ? 1 : 0);
        } else if (op[0] == 'a' && op[1] == 'n') {
            // unreachable with current ordering, kept for completeness
        } else if (op[0] == 'o') {          // ones
            int cnt = 0;
            uint64_t x = state;
            while (x) {
                cnt += (int)(x & 1ULL);
                x >>= 1;
            }
            printf("%d\n", cnt);
        } else if (op[0] == 'z') {          // zeroes
            int cnt = 0;
            uint64_t x = state;
            while (x) {
                cnt += (int)(x & 1ULL);
                x >>= 1;
            }
            printf("%d\n", 64 - cnt);
        }
    }

