                    System.out.println(isSet ? 1 : 0);
                    break;

                case "set":
                    int setBit = scanner.nextInt();
                    state |= (1L << setBit);
                    break;

                case "clear":
                    int clearBit = scanner.nextInt();
                    state &= ~(1L << clearBit);
                    break;

                case "flip":
                    int flipBit = scanner.nextInt();
                    state ^= (1L << flipBit);
                    break;

                case "all":
                    System.out.println(state == -1L ? 1 : 0);
                    break;

                case "any":
                    System.out.println(state != 0 ? 1 : 0);
                    break;

                case "none":
                    System.out.println(state == 0 ? 1 : 0);
                    break;

                case "count":
                    System.out.println(Long.bitCount(state));
                    break;

