public class Main {
    public static void main(String[] args) throws Exception {
        // Since the statement provides no concrete input format,
        // this program reads commands until EOF and applies them
        // to a 64-bit state of flags.
        //
        // Supported commands:
        // TEST i    -> prints 1 if bit i is ON, else 0
        // SET i     -> turns bit i ON
        // CLEAR i   -> turns bit i OFF
        // FLIP i    -> toggles bit i
        // COUNT     -> prints number of ON bits
        // ANY       -> prints 1 if any bit is ON, else 0
        // NONE      -> prints 1 if all bits are OFF, else 0
        // ALL       -> prints 1 if all 64 bits are ON, else 0
        // VALUE     -> prints the current unsigned 64-bit value
        //
        // Bit indices are assumed to be in [0, 63].

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder out = new StringBuilder();

        long state = 0L;
        String line;

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;

            String[] parts = line.split("\\s+");
            String cmd = parts[0].toUpperCase(Locale.ROOT);

            switch (cmd) {
                case "TEST": {
                    int i = Integer.parseInt(parts[1]);
                    out.append(((state >>> i) & 1L) == 1L ? 1 : 0).append('\n');
                    break;
                }
                case "SET": {
                    int i = Integer.parseInt(parts[1]);
                    state |= (1L << i);
                    break;
                }
                case "CLEAR": {
                    int i = Integer.parseInt(parts[1]);
                    state &= ~(1L << i);
                    break;
                }
                case "FLIP": {
                    int i = Integer.parseInt(parts[1]);
                    state ^= (1L << i);
                    break;
                }
                case "COUNT": {
                    out.append(Long.bitCount(state)).append('\n');
                    break;
                }
                case "ANY": {
                    out.append(state != 0L ? 1 : 0).append('\n');
                    break;
                }
                case "NONE": {
                    out.append(state == 0L ? 1 : 0).append('\n');
                    break;
                }
                case "ALL": {
                    out.append(state == -1L ? 1 : 0).append('\n');
                    break;
                }
                case "VALUE": {
                    out.append(Long.toUnsignedString(state)).append('\n');
                    break;
                }
                default:
                    // Ignore unknown commands.
                    break;
            }
        }

        System.out.print(out.toString());
    }
}

import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Initialize state as 64-bit integer with all flags OFF
    state = 0
    out_lines = []

    i = 0
    n = int(data[i])
    i += 1

    for _ in range(n):
        op = data[i]
        i += 1

        if op == "test":
            idx = int(data[i])
            i += 1
            bit = (state >> idx) & 1
            out_lines.append(str(bit))

        elif op == "set":
            idx = int(data[i])
            i += 1
            state |= (1 << idx)

        elif op == "clear":
            idx = int(data[i])
            i += 1
            state &= ~(1 << idx)

        elif op == "flip":
            idx = int(data[i])
            i += 1
            state ^= (1 << idx)

        elif op == "all":
            # all flags ON?
            if state == (1 << 64) - 1:
                out_lines.append("true")
            else:
                out_lines.append("false")

        elif op == "any":
            # any flag ON?
            if state != 0:
                out_lines.append("true")
            else:
                out_lines.append("false")

        elif op == "none":
            # no flag ON?
            if state == 0:
                out_lines.append("true")
            else:
                out_lines.append("false")

        elif op == "count":
            # number of ON flags
            cnt = bin(state).count("1")
            out_lines.append(str(cnt))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

